// Wraps tools/art/lib.js and every module in tools/art/index.js into src/artsrc.js so the game can run the art
// templates live (that is how the characters animate). A tiny CommonJS shim resolves require('./lib') and friends
// by basename, so modules may live in subfolders.
const fs = require('fs'); const path = require('path');
const dir = path.join(__dirname, 'art'); const list = require('./art/index.js');
const base = (p) => p.replace(/\.js$/, '').replace(/^.*\//, '');
const wrap = (key, src) => `define(${JSON.stringify(key)}, function (module, exports, require) {\n${src}\n});\n`;
let out = `// Generated by tools/bundle-src.js from tools/art/*.js — do not edit by hand; edit the templates and rerun it.\n`;
out += `const ARTSRC = (() => {\n  const defs = {}, cache = {};\n  const define = (k, fn) => { defs[k] = fn; };\n  const require = (p) => { const k = p.replace(/\\.js$/, '').replace(/^.*\\//, ''); if (!cache[k]) { if (!defs[k]) throw new Error('art module ' + k); const module = { exports: {} }; cache[k] = module.exports; defs[k](module, module.exports, require); cache[k] = module.exports; } return cache[k]; };\n`;
out += wrap('lib', fs.readFileSync(path.join(dir, 'lib.js'), 'utf8'));
const keys = [];
for (const name of list) { const file = path.join(dir, name + '.js'); if (!fs.existsSync(file)) continue; const k = base(name); keys.push(k); out += wrap(k, fs.readFileSync(file, 'utf8')); }
out += `  const mods = { lib: require('lib') };\n  for (const k of ${JSON.stringify(keys)}) { try { mods[k] = require(k); } catch (e) { console.error('art module ' + k + ' failed: ' + e.message); } }\n  return mods;\n})();\n`;
const oi = process.argv.indexOf('--out'); const dest = oi >= 0 ? process.argv[oi + 1] : path.join(__dirname, '..', 'src', 'artsrc.js'); // --out <file> writes a private bundle (for testing one module without touching src/)
fs.writeFileSync(dest, out);
console.log(`bundled lib + ${keys.length} modules (${(out.length / 1024).toFixed(0)} KB) into ${dest}`);
